CREATE TABLE IF NOT EXISTS "fa_shop_address" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" int NULL DEFAULT NULL,
  "province_id" int NULL DEFAULT NULL,
  "city_id" int NULL DEFAULT NULL,
  "area_id" int NULL DEFAULT NULL,
  "receiver" varchar(255) NULL DEFAULT NULL,
  "mobile" varchar(20) NULL DEFAULT NULL,
  "address" varchar(255) NULL DEFAULT NULL,
  "zipcode" varchar(60) NULL DEFAULT NULL,
  "usednums" int NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "deletetime" bigint NULL DEFAULT NULL,
  "isdefault" smallint NULL DEFAULT 0,
  "status" varchar(30) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_address_user_id" ON "fa_shop_address" ("user_id");

CREATE TABLE IF NOT EXISTS "fa_shop_area" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "pid" int DEFAULT NULL,
  "level" smallint DEFAULT '0',
  "name" varchar(100) DEFAULT '',
  "pinyin" varchar(100) DEFAULT '',
  "py" varchar(50) DEFAULT '',
  "adcode" varchar(50) DEFAULT '',
  "zipcode" varchar(50) DEFAULT '',
  "lng" varchar(30) DEFAULT NULL,
  "lat" varchar(30) DEFAULT NULL,
  "status" varchar(255) DEFAULT 'normal',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_area_pid" ON "fa_shop_area" ("pid");

CREATE TABLE IF NOT EXISTS "fa_shop_block" (
  "id" smallint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" varchar(30) NOT NULL DEFAULT '',
  "name" varchar(50) NOT NULL DEFAULT '',
  "title" varchar(100) NOT NULL DEFAULT '',
  "image" varchar(255) NOT NULL DEFAULT '',
  "url" varchar(255) NOT NULL DEFAULT '',
  "content" text NULL,
  "parsetpl" smallint DEFAULT '0',
  "weigh" int NOT NULL DEFAULT 0,
  "begintime" bigint DEFAULT NULL,
  "endtime" bigint DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_carts" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" int NOT NULL DEFAULT 0,
  "goods_id" int NOT NULL DEFAULT 0,
  "goods_sku_id" int NULL DEFAULT 0,
  "sceneval" smallint NULL DEFAULT 1,
  "nums" smallint NOT NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_carts_user_id" ON "fa_shop_carts" ("user_id");

CREATE TABLE IF NOT EXISTS "fa_shop_category" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" smallint DEFAULT NULL,
  "pid" int NOT NULL DEFAULT '0',
  "isnav" smallint DEFAULT '0',
  "name" varchar(30) NOT NULL DEFAULT '',
  "nickname" varchar(50) NOT NULL DEFAULT '',
  "outlink" varchar(255) DEFAULT NULL,
  "flag" varchar(255) NOT NULL DEFAULT '',
  "image" varchar(255) NOT NULL DEFAULT '',
  "keywords" varchar(255) NOT NULL DEFAULT '',
  "description" varchar(255) NOT NULL DEFAULT '',
  "icon" varchar(50) NOT NULL DEFAULT '',
  "diyname" varchar(30) NOT NULL DEFAULT '',
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "weigh" int NOT NULL DEFAULT '0',
  "status" varchar(30) NOT NULL DEFAULT '',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_category_weigh" ON "fa_shop_category" ("weigh", "id");
CREATE INDEX IF NOT EXISTS "fa_shop_category_pid" ON "fa_shop_category" ("pid");

CREATE TABLE IF NOT EXISTS "fa_shop_collect" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" int NULL DEFAULT NULL,
  "goods_id" int NULL DEFAULT NULL,
  "status" smallint NULL DEFAULT 1,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_comment" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "pid" int NOT NULL DEFAULT 0,
  "user_id" int NOT NULL DEFAULT 0,
  "order_id" int NULL DEFAULT NULL,
  "goods_id" int NOT NULL DEFAULT 0,
  "star" smallint NOT NULL DEFAULT 0,
  "content" text NULL,
  "comments" int NOT NULL DEFAULT 0,
  "images" varchar(1500) NULL DEFAULT NULL,
  "ip" varchar(50) NOT NULL DEFAULT '',
  "useragent" varchar(255) NOT NULL DEFAULT '',
  "subscribe" smallint NOT NULL DEFAULT 0,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_comment_post_id" ON "fa_shop_comment" ("goods_id");

CREATE TABLE IF NOT EXISTS "fa_shop_freight" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(255) NULL DEFAULT NULL,
  "type" smallint NULL DEFAULT NULL,
  "weigh" int NOT NULL DEFAULT 0,
  "switch" smallint NOT NULL DEFAULT 0,
  "num" numeric(10, 2) NULL DEFAULT 0,
  "price" numeric(10, 2) NULL DEFAULT 0.00,
  "continue_num" numeric(10, 2) NULL DEFAULT 0,
  "continue_price" numeric(10, 2) NULL DEFAULT 0.00,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_freight_items" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "freight_id" int NULL DEFAULT NULL,
  "first_num" numeric(10, 2) NULL DEFAULT 0,
  "first_price" numeric(10, 2) NULL DEFAULT 0.00,
  "continue_num" numeric(10, 2) NULL DEFAULT 0,
  "continue_price" numeric(10, 2) NULL DEFAULT 0.00,
  "area_ids" text,
  "type" smallint NOT NULL DEFAULT 0,
  "postage_area_ids" text,
  "postage_num" numeric(10, 2) NULL DEFAULT 0,
  "postage_price" numeric(10, 2) NULL DEFAULT 0.00,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_goods" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "category_id" int NOT NULL DEFAULT '0',
  "subtitle" varchar(255) DEFAULT NULL,
  "attribute_ids" varchar(255) DEFAULT NULL,
  "brand_id" int DEFAULT NULL,
  "goods_sn" varchar(100) NOT NULL DEFAULT '',
  "title" varchar(100) NOT NULL DEFAULT '',
  "keywords" varchar(100) DEFAULT '',
  "description" varchar(255) DEFAULT '',
  "marketprice" numeric(10,2) NOT NULL DEFAULT '0.00',
  "price" numeric(10,2) NOT NULL DEFAULT '0.00',
  "stocks" int NOT NULL DEFAULT '0',
  "sales" int NOT NULL DEFAULT '0',
  "guarantee_ids" varchar(50) DEFAULT NULL,
  "star" int DEFAULT '0',
  "views" int NOT NULL DEFAULT '0',
  "comments" int NOT NULL DEFAULT '0',
  "shares" int NOT NULL DEFAULT '0',
  "image" varchar(255) DEFAULT '',
  "images" varchar(1500) DEFAULT '',
  "content" text,
  "corner" varchar(10) DEFAULT NULL,
  "flag" varchar(255) DEFAULT '',
  "spectype" smallint DEFAULT '0',
  "weight" numeric(10,2) DEFAULT '0.00',
  "isvirtual" smallint NOT NULL DEFAULT '0',
  "freight_id" int DEFAULT NULL,
  "weigh" int NOT NULL DEFAULT '1',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "deletetime" bigint DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_goods_category_id" ON "fa_shop_goods" ("category_id");

CREATE TABLE IF NOT EXISTS "fa_shop_goods_sku" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "goods_id" int NOT NULL DEFAULT 0,
  "goods_sn" varchar(100) NOT NULL DEFAULT '',
  "sku_id" varchar(100) NOT NULL DEFAULT '',
  "image" varchar(255) NOT NULL DEFAULT '',
  "price" numeric(10, 2) NOT NULL DEFAULT 0.00,
  "marketprice" numeric(10, 2) NOT NULL DEFAULT 0.00,
  "stocks" int NOT NULL DEFAULT 0,
  "sales" int NOT NULL DEFAULT 0,
  "weigh" int NOT NULL DEFAULT 0,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_goods_sku_spec" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "goods_id" int NOT NULL DEFAULT 0,
  "spec_id" int NOT NULL DEFAULT 0,
  "spec_value_id" int NOT NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_menu" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "pid" int NOT NULL DEFAULT 0,
  "name" varchar(50)  NULL DEFAULT '',
  "url" varchar(255)  NULL DEFAULT '',
  "weigh" int NOT NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "status" varchar(30)  NULL DEFAULT '',
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_navigation" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(50)  NULL DEFAULT NULL,
  "size" int NULL DEFAULT 60,
  "image" varchar(255)  NULL DEFAULT NULL,
  "path" varchar(255)  NULL DEFAULT NULL,
  "switch" smallint NOT NULL DEFAULT 0,
  "weigh" int NOT NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_order" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_sn" varchar(50) NOT NULL DEFAULT '',
  "user_id" int NOT NULL DEFAULT '0',
  "address_id" int DEFAULT NULL,
  "province_id" int NULL DEFAULT NULL,
  "city_id" int NULL DEFAULT NULL,
  "area_id" int NULL DEFAULT NULL,
  "user_coupon_id" int DEFAULT NULL,
  "openid" varchar(100) DEFAULT NULL,
  "receiver" varchar(60) NOT NULL DEFAULT '',
  "address" varchar(255) NOT NULL DEFAULT '',
  "zipcode" varchar(60) DEFAULT '',
  "mobile" varchar(60) DEFAULT '',
  "amount" numeric(10,2) NOT NULL DEFAULT '0.00',
  "discount" numeric(10,2) NOT NULL DEFAULT '0.00',
  "shippingfee" numeric(10,2) NOT NULL DEFAULT '0.00',
  "goodsprice" numeric(10,2) NOT NULL DEFAULT '0.00',
  "saleamount" numeric(10,2) NOT NULL DEFAULT '0.00',
  "payamount" numeric(10,2) NOT NULL DEFAULT '0.00',
  "paytype" varchar(100) NOT NULL DEFAULT '',
  "method" varchar(50) DEFAULT NULL,
  "transactionid" varchar(100) DEFAULT NULL,
  "expressname" varchar(50) DEFAULT '',
  "expressno" varchar(50) DEFAULT '',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "expiretime" bigint DEFAULT NULL,
  "paytime" bigint DEFAULT NULL,
  "refundtime" bigint DEFAULT NULL,
  "shippingtime" bigint DEFAULT NULL,
  "receivetime" bigint DEFAULT NULL,
  "canceltime" bigint DEFAULT NULL,
  "deletetime" bigint DEFAULT NULL,
  "orderstate" smallint NOT NULL DEFAULT '0',
  "shippingstate" smallint NOT NULL DEFAULT '0',
  "paystate" smallint NOT NULL DEFAULT '0',
  "memo" varchar(255) DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_order_order_sn" UNIQUE ("order_sn")
);
CREATE INDEX IF NOT EXISTS "fa_shop_order_user_id" ON "fa_shop_order" ("user_id");
CREATE INDEX IF NOT EXISTS "fa_shop_order_orderstate" ON "fa_shop_order" ("orderstate");
CREATE INDEX IF NOT EXISTS "fa_shop_order_paytime" ON "fa_shop_order" ("paytime");
CREATE INDEX IF NOT EXISTS "fa_shop_order_createtime" ON "fa_shop_order" ("createtime");
CREATE INDEX IF NOT EXISTS "fa_shop_order_province_city_area" ON "fa_shop_order" ("province_id", "city_id", "area_id");

CREATE TABLE IF NOT EXISTS "fa_shop_order_aftersales" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" int DEFAULT NULL,
  "order_goods_id" int DEFAULT NULL,
  "user_id" int DEFAULT NULL,
  "type" smallint NOT NULL DEFAULT '1',
  "nums" int NULL DEFAULT 0,
  "realprice" numeric(10,2) NULL DEFAULT '0.00',
  "shippingfee" smallint NULL DEFAULT 0,
  "refund" numeric(10,2) NOT NULL DEFAULT '0.00',
  "reason" varchar(255) NOT NULL,
  "images" varchar(2500) DEFAULT NULL,
  "mark" varchar(255) DEFAULT NULL,
  "status" smallint DEFAULT '1',
  "expressname" varchar(50) DEFAULT '',
  "expressno" varchar(50) DEFAULT '',
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_order_action" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_sn" varchar(50) NOT NULL DEFAULT '0',
  "operator" varchar(30) NOT NULL DEFAULT '',
  "memo" varchar(255) NOT NULL DEFAULT '',
  "createtime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_order_action_order_id" ON "fa_shop_order_action" ("order_sn");

CREATE TABLE IF NOT EXISTS "fa_shop_order_goods" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_sn" varchar(50) NOT NULL DEFAULT '0',
  "goods_sn" varchar(100) NOT NULL DEFAULT '',
  "goods_id" int NOT NULL DEFAULT 0,
  "goods_sku_id" int NULL DEFAULT NULL,
  "title" varchar(255) NULL DEFAULT NULL,
  "nums" smallint NOT NULL DEFAULT 1,
  "marketprice" numeric(10, 2) NOT NULL DEFAULT 0.00,
  "price" numeric(10, 2) NOT NULL DEFAULT 0.00,
  "realprice" numeric(10,2) DEFAULT 0.00,
  "salestate" smallint DEFAULT '0',
  "commentstate" smallint DEFAULT '0',
  "attrdata" varchar(1500) NULL DEFAULT NULL,
  "image" varchar(255) NULL DEFAULT NULL,
  "weight" numeric(10,2) DEFAULT '0.00',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_order_goods_order_id" ON "fa_shop_order_goods" ("order_sn");
CREATE INDEX IF NOT EXISTS "fa_shop_order_goods_goods_id" ON "fa_shop_order_goods" ("goods_id");

CREATE TABLE IF NOT EXISTS "fa_shop_spec" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(100) NOT NULL DEFAULT '',
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_spec_value" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "spec_id" int NOT NULL,
  "value" varchar(255) NOT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_electronics_order" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "shipper_id" int NULL DEFAULT NULL,
  "paytype" smallint NULL DEFAULT 1,
  "customer_name" varchar(100) NULL DEFAULT NULL,
  "customer_pwd" varchar(100) NULL DEFAULT NULL,
  "send_site" varchar(100) NULL DEFAULT NULL,
  "send_staff" varchar(100) NULL DEFAULT NULL,
  "month_code" varchar(100) NULL DEFAULT NULL,
  "is_notice" smallint NULL DEFAULT 0,
  "is_return_temp" smallint NULL DEFAULT NULL,
  "is_send_message" smallint NULL DEFAULT NULL,
  "template_size" varchar(10) NULL DEFAULT NULL,
  "operate_require" varchar(255) NULL DEFAULT NULL,
  "logistic_code" varchar(255) NULL DEFAULT NULL,
  "start_date" int NULL DEFAULT NULL,
  "end_date" int NULL DEFAULT NULL,
  "remark" varchar(255) NULL DEFAULT NULL,
  "exp_type" smallint NULL DEFAULT NULL,
  "is_return_sign_bill" smallint NULL DEFAULT NULL,
  "company" varchar(255) NULL DEFAULT NULL,
  "province_name" varchar(50) NULL DEFAULT NULL,
  "city_name" varchar(50) NULL DEFAULT NULL,
  "exp_area_name" varchar(50) NULL DEFAULT NULL,
  "address" varchar(255) NULL DEFAULT NULL,
  "name" varchar(50) NULL DEFAULT NULL,
  "tel" varchar(20) NULL DEFAULT NULL,
  "mobile" varchar(15) NULL DEFAULT NULL,
  "post_code" varchar(15) NULL DEFAULT NULL,
  "title" varchar(255) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_shipper" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(120) NULL DEFAULT NULL,
  "shipper_code" varchar(100) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_order_electronics" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_sn" varchar(50)  NULL DEFAULT NULL,
  "print_template" text  NULL,
  "kdn_order_code" varchar(100)  NULL DEFAULT NULL,
  "logistic_code" varchar(50)  NULL DEFAULT NULL,
  "shipper_code" varchar(30)  NULL DEFAULT NULL,
  "order" varchar(255) NULL DEFAULT NULL,
  "customer_name" varchar(100) NULL DEFAULT NULL,
  "customer_pwd" varchar(100) NULL DEFAULT NULL,
  "status" smallint NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_sku_template" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(50) NULL DEFAULT NULL,
  "spec_names" varchar(150) NULL DEFAULT NULL,
  "spec_values" varchar(250) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_guarantee" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
