  "image" varchar(255) NOT NULL DEFAULT '',
  "intro" varchar(255) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_page" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "category_id" int NOT NULL DEFAULT '0',
  "admin_id" int DEFAULT '0',
  "type" varchar(50) DEFAULT '',
  "title" varchar(50) DEFAULT '',
  "seotitle" varchar(255) DEFAULT '',
  "keywords" varchar(255) DEFAULT '',
  "description" varchar(255) DEFAULT '',
  "flag" varchar(100) DEFAULT '',
  "image" varchar(255) DEFAULT '',
  "content" text,
  "icon" varchar(50) DEFAULT '',
  "views" int NOT NULL DEFAULT '0',
  "likes" int NOT NULL DEFAULT '0',
  "dislikes" int NOT NULL DEFAULT '0',
  "diyname" varchar(100) DEFAULT '',
  "showtpl" varchar(50) DEFAULT '',
  "parsetpl" smallint DEFAULT '0',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "deletetime" bigint DEFAULT NULL,
  "weigh" int NOT NULL DEFAULT '0',
  "status" varchar(30) DEFAULT '',
  PRIMARY KEY ("id")
