CREATE INDEX IF NOT EXISTS "fa_shop_page_diyname" ON "fa_shop_page" ("diyname");
CREATE INDEX IF NOT EXISTS "fa_shop_page_type" ON "fa_shop_page" ("type");

CREATE TABLE IF NOT EXISTS "fa_shop_brand" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
