ALTER TABLE "fa_shop_guarantee" ADD COLUMN IF NOT EXISTS "image" VARCHAR(255) NULL;

ALTER TABLE "fa_shop_address" ADD COLUMN IF NOT EXISTS "deletetime" bigint NULL;

ALTER TABLE "fa_shop_order" ADD COLUMN IF NOT EXISTS "goodsprice" numeric(10, 2) NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS "fa_shop_order_paytime" ON "fa_shop_order" ("paytime");
CREATE INDEX IF NOT EXISTS "fa_shop_order_createtime" ON "fa_shop_order" ("createtime");
CREATE INDEX IF NOT EXISTS "fa_shop_order_province_city_area" ON "fa_shop_order" ("province_id", "city_id", "area_id");

ALTER TABLE "fa_shop_order_aftersales" ADD COLUMN IF NOT EXISTS "nums" int NULL DEFAULT 0;
ALTER TABLE "fa_shop_order_aftersales" ADD COLUMN IF NOT EXISTS "realprice" numeric(10, 2) NULL DEFAULT 0;
ALTER TABLE "fa_shop_order_aftersales" ADD COLUMN IF NOT EXISTS "shippingfee" numeric(10,2) NULL DEFAULT '0.00';

CREATE TABLE IF NOT EXISTS "fa_shop_attribute" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "category_id" int NULL DEFAULT NULL,
  "is_search" smallint NULL DEFAULT 0,
  "is_must" smallint NULL DEFAULT 0,
  "type" varchar(255) NULL DEFAULT 'radio',
  "name" varchar(100) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_attribute_value" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "attribute_id" int NULL DEFAULT NULL,
  "name" varchar(100) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_coupon" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(100) NULL DEFAULT NULL,
  "condition_ids" varchar(50) NULL DEFAULT NULL,
  "result" smallint NULL DEFAULT NULL,
  "result_data" varchar(255) NULL DEFAULT NULL,
  "mode" varchar(255) NULL DEFAULT 'dates',
  "is_private" varchar(255) NULL DEFAULT 'no',
  "is_open" smallint NULL DEFAULT 1,
  "allow_num" int NULL DEFAULT 1,
  "give_num" int NULL DEFAULT 1,
  "received_num" int NULL DEFAULT 0,
  "receive_times" varchar(100) NULL DEFAULT NULL,
  "begintime" bigint NULL DEFAULT NULL,
  "endtime" bigint NULL DEFAULT NULL,
  "use_times" varchar(100) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_coupon_condition" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(100) NULL DEFAULT NULL,
  "type" smallint NULL DEFAULT NULL,
  "content" varchar(100) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_exchange" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" varchar(255) NULL DEFAULT NULL,
  "title" varchar(255) NULL DEFAULT NULL,
  "description" varchar(255) NULL DEFAULT NULL,
  "content" text,
  "image" varchar(225) NULL DEFAULT NULL,
  "score" int NULL DEFAULT 0,
  "stocks" int NULL DEFAULT 0,
  "sales" int NULL DEFAULT 0,
  "weigh" int NOT NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "status" varchar(255) NULL DEFAULT 'normal',
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_exchange_order" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" int NULL DEFAULT 0,
  "exchange_id" int NULL DEFAULT 0,
  "type" varchar(50) NULL DEFAULT NULL,
  "orderid" varchar(50) NULL DEFAULT NULL,
  "nums" int NULL DEFAULT 0,
  "score" int NULL DEFAULT 0,
  "receiver" varchar(30) NULL DEFAULT NULL,
  "mobile" varchar(30) NULL DEFAULT NULL,
  "address" varchar(100) NULL DEFAULT NULL,
  "memo" varchar(255) NULL DEFAULT NULL,
  "reason" varchar(100) NULL DEFAULT NULL,
  "expressname" varchar(50) NULL DEFAULT NULL,
  "expressno" varchar(50) NULL DEFAULT NULL,
  "ip" varchar(50) NULL DEFAULT NULL,
  "useragent" varchar(255) NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  "status" varchar(255) NULL DEFAULT 'created',
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_goods_attr" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "attribute_id" int NULL DEFAULT NULL,
  "value_id" int NULL DEFAULT NULL,
  "goods_id" int NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_goods_attr_attribute" ON "fa_shop_goods_attr" ("attribute_id", "value_id", "goods_id");

CREATE TABLE IF NOT EXISTS "fa_shop_subscribe_log" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" int NULL DEFAULT NULL,
  "order_sn" varchar(50) NULL DEFAULT NULL,
  "tpl_id" varchar(100) NULL DEFAULT NULL,
  "status" smallint NULL DEFAULT 0,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_template_msg" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" smallint NULL DEFAULT 1,
  "event" smallint NOT NULL DEFAULT 0,
  "title" varchar(150) NULL DEFAULT NULL,
  "tpl_id" varchar(50) NULL DEFAULT NULL,
  "content" varchar(500) NULL DEFAULT NULL,
  "extend" text NOT NULL,
  "page" varchar(100) NULL DEFAULT NULL,
  "switch" smallint NOT NULL DEFAULT 0,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_user_coupon" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "coupon_id" int NULL DEFAULT NULL,
  "user_id" int NULL DEFAULT NULL,
  "is_used" smallint NULL DEFAULT 1,
  "begin_time" bigint NULL DEFAULT NULL,
  "expire_time" bigint NULL DEFAULT NULL,
  "createtime" bigint NULL DEFAULT NULL,
  "updatetime" bigint NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_card" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" smallint DEFAULT '0',
  "title" varchar(100) DEFAULT NULL,
  "content" text,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id")
);


ALTER TABLE "fa_shop_order_goods" ADD COLUMN IF NOT EXISTS "realprice" numeric(10, 2) NULL DEFAULT 0.00;

ALTER TABLE "fa_shop_order" ADD COLUMN IF NOT EXISTS "openid" varchar(100) NULL DEFAULT '';

